-- ============================================================
-- DramaForge 数据契约 · PostgreSQL 版（Supabase 用）
-- 与 server/src/db/schema.sql（SQLite 版）字段完全一致，仅做方言转换：
--   INTEGER PRIMARY KEY AUTOINCREMENT -> bigint generated by default as identity
--   TEXT 时间戳                        -> timestamptz
--   JSON 列                            -> text（后端仍存 JSON 字符串，保持零改动）
--   标志位                             -> integer（0/1，与原逻辑一致）
--
-- 执行方式：Supabase Dashboard -> SQL Editor -> 粘贴全文 -> Run（只需跑一次）
-- ============================================================

-- ---------- 项目 ----------
create table if not exists dramas (
  id             bigint generated by default as identity primary key,
  title          text not null,
  description    text,
  genre          text,
  style          text,
  audience       text,
  inspiration    text,
  aspect_ratio   text default '9:16',
  resolution     text default '1080p',
  total_episodes integer default 0,
  status         text default 'draft'
                 check (status in ('draft','writing','producing','done')),
  thumbnail      text,
  tags           text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  deleted_at     timestamptz
);
create index if not exists idx_dramas_status on dramas(status) where deleted_at is null;

-- ---------- 剧集 ----------
create table if not exists episodes (
  id             bigint generated by default as identity primary key,
  drama_id       bigint not null references dramas(id) on delete cascade,
  episode_number integer not null,
  title          text,
  content        text,
  script_content text,
  outline        text,
  hook_type      text,
  duration_sec   integer default 0,
  status         text default 'draft'
                 check (status in ('draft','scripted','storied','done')),
  video_url      text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  deleted_at     timestamptz
);
create unique index if not exists uq_episodes_num
  on episodes(drama_id, episode_number) where deleted_at is null;
create index if not exists idx_episodes_drama on episodes(drama_id);

-- ---------- 角色（项目级，跨集共享） ----------
create table if not exists characters (
  id               bigint generated by default as identity primary key,
  drama_id         bigint not null references dramas(id) on delete cascade,
  name             text not null,
  role             text,
  description      text,
  appearance       text,
  styling          text,
  personality      text,
  final_prompt     text,
  image_url        text,
  reference_images text,
  seed_value       integer,
  sort_order       integer default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  deleted_at       timestamptz
);
create unique index if not exists uq_characters_name
  on characters(drama_id, lower(trim(name))) where deleted_at is null;
create index if not exists idx_characters_drama on characters(drama_id);

-- ---------- 场景 ----------
create table if not exists scenes (
  id           bigint generated by default as identity primary key,
  drama_id     bigint not null references dramas(id) on delete cascade,
  location     text not null,
  time_of_day  text not null default '日',
  prompt       text,
  lighting     text,
  final_prompt text,
  image_url    text,
  status       text default 'pending'
               check (status in ('pending','processing','done','failed')),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz
);
create unique index if not exists uq_scenes_loc
  on scenes(drama_id, lower(trim(location)), time_of_day) where deleted_at is null;
create index if not exists idx_scenes_drama on scenes(drama_id);

-- ---------- 道具 ----------
create table if not exists props (
  id           bigint generated by default as identity primary key,
  drama_id     bigint not null references dramas(id) on delete cascade,
  name         text not null,
  type         text,
  description  text,
  prompt       text,
  final_prompt text,
  image_url    text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz
);
create unique index if not exists uq_props_name
  on props(drama_id, lower(trim(name))) where deleted_at is null;
create index if not exists idx_props_drama on props(drama_id);

-- ---------- 分镜 ----------
create table if not exists storyboards (
  id                bigint generated by default as identity primary key,
  episode_id        bigint not null references episodes(id) on delete cascade,
  scene_id          bigint references scenes(id) on delete set null,
  storyboard_number integer not null,
  title             text,
  location          text,
  time_of_day       text,
  shot_type         text,
  angle             text,
  movement          text,
  result            text,
  atmosphere        text,
  image_prompt      text,
  video_prompt      text,
  bgm_prompt        text,
  sound_effect      text,
  description       text,
  duration_sec      real default 10,
  first_frame_image text,
  last_frame_image  text,
  composed_image    text,
  reference_images  text,
  video_url         text,
  subtitle_url      text,
  status            text default 'pending'
                    check (status in ('pending','prompted','imaging','imaged','videoing','done','failed')),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create unique index if not exists uq_storyboards_num on storyboards(episode_id, storyboard_number);
create index if not exists idx_storyboards_episode on storyboards(episode_id);

-- ---------- 桥表 ----------
create table if not exists episode_characters (
  episode_id   bigint not null references episodes(id) on delete cascade,
  character_id bigint not null references characters(id) on delete cascade,
  primary key (episode_id, character_id)
);
create table if not exists episode_scenes (
  episode_id bigint not null references episodes(id) on delete cascade,
  scene_id   bigint not null references scenes(id) on delete cascade,
  primary key (episode_id, scene_id)
);
create table if not exists episode_props (
  episode_id bigint not null references episodes(id) on delete cascade,
  prop_id    bigint not null references props(id) on delete cascade,
  primary key (episode_id, prop_id)
);
create table if not exists storyboard_characters (
  storyboard_id bigint not null references storyboards(id) on delete cascade,
  character_id  bigint not null references characters(id) on delete cascade,
  primary key (storyboard_id, character_id)
);
create table if not exists storyboard_props (
  storyboard_id bigint not null references storyboards(id) on delete cascade,
  prop_id       bigint not null references props(id) on delete cascade,
  primary key (storyboard_id, prop_id)
);

-- ---------- 画布布局 ----------
create table if not exists canvas_layout (
  id         bigint generated by default as identity primary key,
  drama_id   bigint not null references dramas(id) on delete cascade,
  node_type  text not null
             check (node_type in ('drama','episode','character','scene','prop','storyboard','video')),
  node_id    bigint not null,
  x          real not null default 0,
  y          real not null default 0,
  w          real default 280,
  h          real default 180,
  z_index    integer default 0,
  collapsed  integer default 0,
  updated_at timestamptz not null default now()
);
create unique index if not exists uq_canvas_node on canvas_layout(drama_id, node_type, node_id);
create index if not exists idx_canvas_drama on canvas_layout(drama_id);

-- ---------- 生成任务 ----------
create table if not exists gen_tasks (
  id            bigint generated by default as identity primary key,
  task_type     text not null check (task_type in ('image','video','audio')),
  provider      text,
  model         text,
  prompt        text,
  params        text,
  upstream_id   text,
  result_url    text,
  local_path    text,
  status        text not null default 'processing'
                check (status in ('processing','completed','failed')),
  error_msg     text,
  drama_id      bigint,
  episode_id    bigint,
  storyboard_id bigint,
  target_type   text,
  target_id     bigint,
  created_at    timestamptz not null default now(),
  completed_at  timestamptz
);
create index if not exists idx_tasks_status on gen_tasks(status);
create index if not exists idx_tasks_episode on gen_tasks(episode_id);

-- ---------- 拼接记录 ----------
create table if not exists merges (
  id           bigint generated by default as identity primary key,
  drama_id     bigint not null references dramas(id) on delete cascade,
  episode_id   bigint not null references episodes(id) on delete cascade,
  provider     text,
  model        text,
  status       text not null default 'pending'
               check (status in ('pending','processing','completed','failed')),
  segments     text,
  merged_url   text,
  duration     real,
  error_msg    text,
  created_at   timestamptz not null default now(),
  completed_at timestamptz
);
create index if not exists idx_merges_episode on merges(episode_id);

-- ---------- AI 配置 ----------
create table if not exists ai_configs (
  id             bigint generated by default as identity primary key,
  service_type   text not null,
  provider       text not null,
  name           text not null,
  base_url       text not null,
  api_key        text not null,
  models         text,
  default_model  text,
  endpoint       text,
  query_endpoint text,
  priority       integer default 0,
  is_default     integer default 0,
  is_active      integer default 1,
  settings       text,
  created_at     timestamptz not null default now()
);
create index if not exists idx_ai_type on ai_configs(service_type, is_active);

-- ---------- 助手会话 ----------
create table if not exists chat_sessions (
  id         bigint generated by default as identity primary key,
  drama_id   bigint not null references dramas(id) on delete cascade,
  mode       text not null default 'assistant' check (mode in ('assistant','team')),
  title      text,
  created_at timestamptz not null default now()
);
create table if not exists chat_messages (
  id         bigint generated by default as identity primary key,
  session_id bigint not null references chat_sessions(id) on delete cascade,
  role       text not null check (role in ('user','assistant','tool','system')),
  content    text,
  meta       text,
  created_at timestamptz not null default now()
);
create index if not exists idx_msgs_session on chat_messages(session_id);

-- ---------- 设置 ----------
create table if not exists app_settings (
  key        text primary key,
  value      text,
  updated_at timestamptz not null default now()
);

-- ============================================================
-- RLS：后端用 service_role key 直连，会绕过 RLS；
-- 这里统一开启 RLS 但只放行 service_role，防止 anon key 从浏览器直读。
-- ============================================================
alter table dramas                enable row level security;
alter table episodes              enable row level security;
alter table characters            enable row level security;
alter table scenes                enable row level security;
alter table props                 enable row level security;
alter table storyboards           enable row level security;
alter table episode_characters    enable row level security;
alter table episode_scenes        enable row level security;
alter table episode_props         enable row level security;
alter table storyboard_characters enable row level security;
alter table storyboard_props      enable row level security;
alter table canvas_layout         enable row level security;
alter table gen_tasks             enable row level security;
alter table merges                enable row level security;
alter table ai_configs            enable row level security;
alter table chat_sessions         enable row level security;
alter table chat_messages         enable row level security;
alter table app_settings          enable row level security;
